import { _decorator, Component, Node } from 'cc';
import { World } from '../Engine/World';
import { Bus } from '../Engine/Bus';
import { ViewRegistry } from '../Engine/ViewRegistry';
import { FixedTick } from '../Engine/Tick';
import { GameData } from '../Core/Data/GameData';
import { BulletView } from './View/BulletView';
import { PlayerView } from './View/PlayerView';
import { EnemyView } from './View/EnemyView';
import { FireSystem } from './System/FireSystem';
import { BulletSpawnSystem } from './System/BulletSpawnSystem';
import { PlayerControlSystem } from './System/PlayerControlSystem';
import { EnemySpawnSystem } from './System/EnemySpawnSystem';
import { MovementSystem } from './System/MovementSystem';
import { CombatSystem } from './System/CombatSystem';
import { DamageSystem } from './System/DamageSystem';
import { BattleStateSystem } from './System/BattleStateSystem';
import { OutOfBoundsSystem } from './System/OutOfBoundsSystem';
import { Plane } from './Entity/Plane';
import { BattleInputHandler } from './BattleInputHandler';
import { BATTLE_EVENT } from './BattleEvents';
const { ccclass, } = _decorator;

@ccclass('BattleScene')
export class BattleScene extends Component {

    private _bus: Bus = null!;
    private _world: World = null!;
    private _views: ViewRegistry = null!;
    private _tick: FixedTick = null!;

    protected start(): void {

        GameData.init();
         
        this._bus = new Bus();
        this._views = new ViewRegistry(this.node);
        this._world = new World(this._bus,this._views);

        this._registerViewFactories();
        this._addSystems();
        this._createPlayer();

        this._tick = this.node.addComponent(FixedTick);
        this._tick.setup(this._world, this._views);
        this._tick.begin();
        
        const input = this.node.addComponent(BattleInputHandler);
        input.setup(this._bus);

        // 7. 监听游戏结束
        this._bus.on(BATTLE_EVENT.GAME_OVER, this._onGameOver, this);

    }

    onDestroy(): void {
        this._bus?.off(BATTLE_EVENT.GAME_OVER, this._onGameOver, this);
        this._tick?.stop();
        this._world?.destroy();
    }


    private _registerViewFactories(): void {
        this._views.registerFactory('bullet', (e) => {
            const node = new Node(`bullet_${e.id}`);
            return node.addComponent(BulletView);
            }
        );

        this._views.registerFactory('player', (e) => {
            const node = new Node(`player_${e.id}`);
            return node.addComponent(PlayerView);
            }
        );

        this._views.registerFactory('enemy', (e) => {
            const node = new Node(`enemy_${e.id}`);
            return node.addComponent(EnemyView);
            }
        );
    }

    private _addSystems(): void{
        this._world.addSystem(new FireSystem());
        this._world.addSystem(new BulletSpawnSystem());
        this._world.addSystem(new PlayerControlSystem());
        this._world.addSystem(new EnemySpawnSystem());
        this._world.addSystem(new MovementSystem());
        this._world.addSystem(new CombatSystem());
        this._world.addSystem(new DamageSystem());
        this._world.addSystem(new BattleStateSystem());
        this._world.addSystem(new OutOfBoundsSystem());
    }

    private _createPlayer():void{
        const player = new Plane('player');
        player.x = 0;
        player.y = -GameData.viewH / 2 + 100;
        player.hp = 100;
        player.maxHp = 100;
        player.collisionRadius = 20;
        player.weapons.push({
            fireInterval: 0.2,
            cooldownTimer: 0,
            bulletType: 'blue',
            bulletSpeed: 400,
            bulletDamage: 10,
            fireDirX: 0,
            fireDirY: 1,
            enabled: true,
        });
        this._world.add(player);
    }

    private _onGameOver(): void{
        console.log('[BattleScene] 游戏结束');
        this._tick.stop();
        const input = this.node.getComponent(BattleInputHandler);
        if (input) input.enabled = false;   // 停掉输入
    }

}


